protocolTypes.tsDefinition:
export type WCoreEffectivePolicy = {
  posture: 'smart' | 'managed' | 'dangerous';
  approvals: 'prompt' | 'auto_edit' | 'bypass';
  sandbox: 'required' | 'bypass';
  source:
    | 'default'
    | 'managed'
    | 'user_config'
    | 'project'
    | 'environment'
    | 'local_cli_launch'
    | 'desktop_local_launch'
    | 'protocol'
    | 'acp'
    | 'tui'
    | 'resume'
    | 'child';
  managed_floor_active: boolean;
  /** Present only while a `dangerous` posture activation is live. */
  dangerous_activation_id?: string;
  dangerous_expires_at_unix_ms?: number;
};

export type WCoreExecutionPolicyReceipt = {
  critical: true;
  contract_version: string;
  revision: number;
  reason: 'launch' | 'mode_change' | 'resume' | 'expiry';
  effective_at_unix_ms: number;
  policy: WCoreEffectivePolicy;
};

| {
    type: 'ready';
    version: string;
    session_id?: string;
    capabilities: WCoreCapabilities;
    /**
     * Revision-0 policy receipt. The core-event schema marks it REQUIRED on
     * `ready`, but compat/events/ready.minimal.json ships a `ready` with no
     * `execution_policy` at all - so it must be optional in TS. Absent =
     * pre-policy engine; the tracker stays uninitialised rather than
     * assuming revision 0.
     */
    execution_policy?: WCoreExecutionPolicyReceipt;
  }

// The producer emits this (wcore-cli/src/main.rs) but NO payload schema
// exists anywhere in the bundle: producer-complete.schema.json gives it only
// a bare `type` discriminator with additionalProperties:true and zero declared
// properties. Model the tag only - inventing fields here would be a guess.
| { type: 'workspace_policy' }
